import{_ as p,a0 as a,w as i,s as l,ao as u,I as r,x as e,a1 as o,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"10個在隨機出現在面試中的Linux問題及答案 | LCTT x X-CMD","titleTemplate":false,"description":"10個在隨機出現在面試中的Linux問題及答案 | LCTT (201404) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"10個在隨機出現在面試中的Linux問題及答案 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"10個在隨機出現在面試中的Linux問題及答案 | LCTT (201404) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201404/10 Useful Random Linux Interview Questions and Answers_t","title":"10個在隨機出現在面試中的Linux問題及答案","tag":"201404","desc":""},"relativePath":"201404/10 Useful Random Linux Interview Questions and Answers_t.md","filePath":"[post].md"}'),d={name:"201404/10 Useful Random Linux Interview Questions and Answers_t.md"};function c(m,t,g,w,f,h){const n=a("Link");return i(),l("div",null,[t[11]||(t[11]=u(`<h1 id="_10個在隨機出現在面試中的linux問題及答案" tabindex="-1">10個在隨機出現在面試中的Linux問題及答案 <a class="header-anchor" href="#_10個在隨機出現在面試中的linux問題及答案" aria-label="Permalink to “10個在隨機出現在面試中的Linux問題及答案”">​</a></h1><p>為了給你們帶來一些小驚喜，這次我們準備了一些在面試中隨機出現的問題而不是專門關於某個領域的問題。這些問題肯定會在不深入學習新知識的前提下使你在面試中脱穎而出。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/Random-Interview-Questions.png" alt=""></p><p>1.假設你在為你工作的公司維護一份日常的備份。這份備份是以壓縮後的格式而被維護着。現在你需要檢查一份兩個月之前的日誌，你應該提出什麼樣的建議從而可以在不解壓這份備份的前提下完成檢查日誌的任務？</p><blockquote><p><strong>答案</strong>： 在不解壓文件的前提下檢查文件內容，我們需要用到&#39;zcat&#39;。zcat這個工具可以輕鬆完成這個任務。</p></blockquote><pre><code># zcat ­f phpshell­2.4.tar.gz
</code></pre><p>2.你需要追蹤你係統中發生的事件，你應該怎麼做？</p><blockquote><p><strong>答案</strong>： 為了追蹤系統中發生的事件，我們需要用到叫做syslogd的這個後台程序。syslogd這個後台程序可以追蹤系統信息並將其保存到指定的日誌文件中。</p></blockquote><p>啓用&#39;syslogd&#39;這個後台進程會在路徑&#39;/var/log/syslog&#39;中生成一個日誌文件。syslogd應用對解決Linux系統中的問題十分有用。標準生成的日誌文件和下面這個例子很像。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/syslongd.jpg" alt="syslogd"></p><p>3.如何禁止特定IP訪問FTP服務器？</p><blockquote><p><strong>答案</strong>： 我們可以通過運用tcp_wrapper來禁止可疑的IP訪問。首先在路徑&#39;/etc/vsftpd.conf&#39;的配置文件中，將tcp_wrapper這個參數設置為&quot;tcp_wrapper=YES&quot;，然後在&#39;/etc/host.deny&#39;文件中加入可疑的IP地址。</p></blockquote><p><strong>禁止訪問的IP地址</strong></p><p>打開&#39;/etc/hosts.deny&#39;文件。</p><pre><code># vi /etc/hosts.deny
</code></pre><p>在文件底端加入拒絕訪問的IP地址</p><pre><code>#
# hosts.deny    This file contains access rules which are used to
#               deny connections to network services that either use
#               the tcp_wrappers library or that have been
#               started through a tcp_wrappers-enabled xinetd.
#
#               The rules in this file can also be set up in
#               /etc/hosts.allow with a &#39;deny&#39; option instead.
#
#               See &#39;man 5 hosts_options&#39; and &#39;man 5 hosts_access&#39;
#               for information on rule syntax.
#               See &#39;man tcpd&#39; for information on tcp_wrappers
#
vsftpd:172.16.16.1
</code></pre><p>4.告訴我們Telnet和SSH之間的區別？</p><blockquote><p><strong>答案</strong>： Telnet和SSH都是用來遠程管理系統的協議。與Telnet直接傳輸數據正好相反，安全的SSH通信協議需要通信中有密鑰的交換，這説明telnet相比較於SSH不安全。</p></blockquote><p>5.你需要終止你的X server，但當你嘗試殺進程的時候，你遇到了表示不能退出X server的錯誤信息。你準備怎麼做？</p><blockquote><p><strong>答案</strong>： 當你嘗試殺X server的進程時，系統不會讓你像使用&#39;/etc/init.d/gdm stop&#39;一樣正常的退出X server。我們需要執行一個使X server重啓的特別的鍵位組合&#39;Ctrl+ Alt+ BackSpace&#39;。</p></blockquote><p>6.告訴我命令&#39;ping&#39;和&#39;ping6&#39;的區別？</p><blockquote><p><strong>答案</strong>： 這兩個命令有同樣的功能，但&#39;ping6&#39;命令可被用於ipv6的IP地址。</p></blockquote><p>7.你想要在Home目錄下尋找*.tar文件並一次性刪除，你會怎麼做？</p><blockquote><p><strong>答案</strong>： 我們要同時用到find和rm命令來刪除所有*.tar文件</p></blockquote><pre><code># find /home/ ­name &#39;*.tar&#39; | xargs rm ­rf
</code></pre><p>8.locate和slocate命令的區別？</p><blockquote><p><strong>答案</strong>： slocate(secure locate)會尋找所有用户有權限訪問的文件，然而locate會搜索（它的資料庫裏面的）所有更新過的結果。</p></blockquote><p>9.你要在當前目錄中所有“.txt”文件中搜索“Tecmint”這個字符串，你怎麼做？</p><blockquote><p><strong>答案</strong>： 用find命令在當前目錄遞歸尋找文件中的“Tecmint”字符串。</p></blockquote><pre><code># find ­name “*.txt” | xargs grep “Tecmint”
</code></pre><p>10.你要向所有已連接的用户發送“Server is going down for maintenance”這樣一條信息，你怎麼做？</p><blockquote><p><strong>答案</strong>： 運用wall命令就可以很容易地實現，wall命令可以向所有已連接服務器的用户發送信息。</p></blockquote><pre><code># echo please save your work, immediately. The server is going down for Maintenance at 12:30 Pm, sharply. | wall
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/wall.jpg" alt="wall command"></p><hr>`,36)),r("p",null,[t[1]||(t[1]=e("via: ",-1)),o(n,{href:"http://www.tecmint.com/useful-random-linux-interview-questions-and-answers/"},{default:s(()=>[...t[0]||(t[0]=[e("http://www.tecmint.com/useful-random-linux-interview-questions-and-answers/",-1)])]),_:1})]),r("p",null,[t[4]||(t[4]=e("譯者：ThomazL(",-1)),o(n,{href:"https://github.com/ThomazL"},{default:s(()=>[...t[2]||(t[2]=[e("https://github.com/ThomazL",-1)])]),_:1}),t[5]||(t[5]=e(") 校對：",-1)),o(n,{href:"https://github.com/wxy"},{default:s(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[8]||(t[8]=e("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原創翻譯，",-1)),o(n,{href:"http://linux.cn/"},{default:s(()=>[...t[7]||(t[7]=[e("Linux中國",-1)])]),_:1}),t[10]||(t[10]=e(" 榮譽推出",-1))])])}const k=p(d,[["render",c]]);export{b as __pageData,k as default};
